#### StarRating.razor (`Components/StarRating.razor`) — INTERACTIVE component
This is a shared component (not a page), placed in `Components/`. It needs `@rendermode InteractiveServer`.

```razor
@rendermode InteractiveServer
@inject RecipeShare.Services.RecipeService RecipeService

<div class="d-inline-flex align-items-center gap-2">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <button class="btn btn-link p-0 fs-4 text-decoration-none"
                @onclick="() => Rate(star)"
                disabled="@hasRated"
                title="Rate @star star(s)">
            @(star <= displayStars ? "★" : "☆")
        </button>
    }
    @if (hasRated)
    {
        <span class="text-success ms-2">Thanks for rating!</span>
    }
    else
    {
        <span class="text-muted ms-2">Click to rate</span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    private int displayStars;
    private bool hasRated;

    protected override void OnParametersSet()
    {
        var recipe = RecipeService.GetById(RecipeId);
        displayStars = recipe is not null ? (int)Math.Round(recipe.AverageRating) : 0;
    }

    private void Rate(int stars)
    {
        if (hasRated) return;
        RecipeService.AddRating(RecipeId, stars);
        displayStars = stars;
        hasRated = true;
    }
}
```

#### SubmitRecipe.razor (`Components/Pages/SubmitRecipe.razor`) — INTERACTIVE page

This page uses `@rendermode InteractiveServer` since it has a complex form with EditForm.

Use the `collect-user-input` skill patterns for the form. Here's what to implement:

```razor
@page "/submit"
@rendermode InteractiveServer
@using System.ComponentModel.DataAnnotations
@inject RecipeShare.Services.RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe - RecipeShare</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

<EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
    <DataAnnotationsValidator />
    <ValidationSummary class="text-danger" />

    <div class="mb-3">
        <label for="title" class="form-label">Recipe Title</label>
        <InputText id="title" @bind-Value="model.Title" class="form-control" />
        <ValidationMessage For="() => model.Title" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="category" class="form-label">Category</label>
        <InputText id="category" @bind-Value="model.Category" class="form-control" placeholder="e.g., Italian, Mexican, Desserts" />
        <ValidationMessage For="() => model.Category" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="ingredients" class="form-label">Ingredients (one per line)</label>
        <InputTextArea id="ingredients" @bind-Value="model.Ingredients" class="form-control" rows="6" />
        <ValidationMessage For="() => model.Ingredients" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="steps" class="form-label">Steps (one per line)</label>
        <InputTextArea id="steps" @bind-Value="model.Steps" class="form-control" rows="6" />
        <ValidationMessage For="() => model.Steps" class="text-danger" />
    </div>

    <button type="submit" class="btn btn-primary">Submit Recipe</button>
</EditForm>

@if (submitted)
{
    <div class="alert alert-success mt-3">
        Recipe "@submittedTitle" submitted successfully!
        <a href="recipes/@submittedCategory/@submittedId">View your recipe →</a>
    </div>
}

@code {
    private RecipeModel model = new();
    private bool submitted;
    private string submittedTitle = "";
    private string submittedCategory = "";
    private int submittedId;

    private void HandleSubmit()
    {
        var recipe = RecipeService.AddRecipe(model.Title, model.Category, model.Ingredients, model.Steps);
        submittedTitle = recipe.Title;
        submittedCategory = recipe.Category;
        submittedId = recipe.Id;
        submitted = true;
        model = new();
    }

    private class RecipeModel
    {
        [Required(ErrorMessage = "Title is required")]
        [StringLength(100, ErrorMessage = "Title must be 100 characters or fewer")]
        public string Title { get; set; } = "";

        [Required(ErrorMessage = "Category is required")]
        public string Category { get; set; } = "";

        [Required(ErrorMessage = "Ingredients are required")]
        public string Ingredients { get; set; } = "";

        [Required(ErrorMessage = "Steps are required")]
        public string Steps { get; set; } = "";
    }
}
```

