namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public string Category { get; set; } = "";
    public string Ingredients { get; set; } = "";
    public string Steps { get; set; } = "";
    public int TotalRatingPoints { get; set; }
    public int RatingCount { get; set; }
    public double AverageRating => RatingCount > 0 ? (double)TotalRatingPoints / RatingCount : 0;
}

@rendermode InteractiveServer
@inject RecipeShare.Services.RecipeService RecipeService

<div class="d-inline-flex align-items-center gap-2">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <button class="btn btn-link p-0 fs-4 text-decoration-none"
                @onclick="() => Rate(star)"
                disabled="@hasRated"
                title="Rate @star star(s)">
            @(star <= displayStars ? "★" : "☆")
        </button>
    }
    @if (hasRated)
    {
        <span class="text-success ms-2">Thanks for rating!</span>
    }
    else
    {
        <span class="text-muted ms-2">Click to rate</span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    private int displayStars;
    private bool hasRated;

    protected override void OnParametersSet()
    {
        var recipe = RecipeService.GetById(RecipeId);
        displayStars = recipe is not null ? (int)Math.Round(recipe.AverageRating) : 0;
    }

    private void Rate(int stars)
    {
        if (hasRated) return;
        RecipeService.AddRating(RecipeId, stars);
        displayStars = stars;
        hasRated = true;
    }
}

@page "/recipes/{CategoryName}"
@inject RecipeShare.Services.RecipeService RecipeService

<PageTitle>@CategoryName Recipes - RecipeShare</PageTitle>

<h1>@CategoryName Recipes</h1>
<a href="/" class="btn btn-outline-secondary btn-sm mb-3">← Back to Categories</a>

@if (recipes.Count == 0)
{
    <p>No recipes found in this category.</p>
}
else
{
    <div class="row">
        @foreach (var recipe in recipes)
        {
            <div class="col-md-6 mb-3">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text text-muted">
                            @if (recipe.RatingCount > 0)
                            {
                                <span>★ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)</span>
                            }
                            else
                            {
                                <span>No ratings yet</span>
                            }
                        </p>
                        <a href="recipes/@CategoryName/@recipe.Id" class="btn btn-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter] public string CategoryName { get; set; } = "";
    private IReadOnlyList<RecipeShare.Models.Recipe> recipes = [];

