}
else
{
    <a href="recipes/@CategoryName" class="btn btn-outline-secondary btn-sm mb-3">← Back to @CategoryName</a>

    <h1>@recipe.Title</h1>
    <span class="badge bg-secondary mb-3">@recipe.Category</span>

    <div class="mt-3">
        <StarRating RecipeId="recipe.Id" />
    </div>

    <h3 class="mt-4">Ingredients</h3>
    <ul>
