You are implementing a Blazor Web App for a recipe sharing community. The project has already been scaffolded at `/tmp/sv-b093f3bdd71c4ac3a56f44cea01b2384/RecipeShare` using `dotnet new blazor -int Server --no-https`.

The project uses **Interactive Server, per-page** mode. Pages are static SSR by default. Only components that need interactivity get `@rendermode InteractiveServer`.

## Requirements
- Browse recipes by category — read-only content pages (static SSR)
- Each recipe page has a star-rating widget (click to rate 1–5 stars) — needs `@rendermode InteractiveServer`
- A "Submit Recipe" page with a form (title, ingredients, steps) — needs `@rendermode InteractiveServer`
- Homepage displays recipe categories (static content)
- Most pages are read-only; only the rating widget and submit form need interactivity

## Implementation Plan

### 1. Delete template defaults
- Delete `Components/Pages/Counter.razor` and `Components/Pages/Weather.razor` (if they exist)

### 2. Create a data model and service
Create `Models/Recipe.cs`:
```csharp
namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public string Category { get; set; } = "";
    public string Ingredients { get; set; } = "";
    public string Steps { get; set; } = "";
    public int TotalRatingPoints { get; set; }
    public int RatingCount { get; set; }
    public double AverageRating => RatingCount > 0 ? (double)TotalRatingPoints / RatingCount : 0;
}
```

Create `Services/RecipeService.cs` — a singleton in-memory store with seed data:
```csharp
namespace RecipeShare.Services;

using RecipeShare.Models;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough\nSan Marzano tomatoes\nFresh mozzarella\nFresh basil\nOlive oil\nSalt", Steps = "1. Preheat oven to 475°F (245°C).\n2. Roll out dough on a floured surface.\n3. Spread crushed tomatoes evenly.\n4. Tear mozzarella and distribute over sauce.\n5. Bake for 10-12 minutes until crust is golden.\n6. Top with fresh basil and a drizzle of olive oil." },
        new Recipe { Id = 2, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti\nGuanciale or pancetta\nEgg yolks\nPecorino Romano\nBlack pepper", Steps = "1. Cook spaghetti in salted boiling water.\n2. Crisp guanciale in a pan over medium heat.\n3. Whisk egg yolks with grated Pecorino and pepper.\n4. Toss hot pasta with guanciale.\n5. Remove from heat and stir in egg mixture.\n6. Serve immediately with extra cheese." },
        new Recipe { Id = 3, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken thighs\nYogurt\nGaram masala\nTurmeric\nCrushed tomatoes\nHeavy cream\nGarlic\nGinger\nOnion", Steps = "1. Marinate chicken in yogurt and spices for 1 hour.\n2. Grill or broil chicken until charred.\n3. Sauté onion, garlic, and ginger.\n4. Add crushed tomatoes and simmer 15 minutes.\n5. Stir in cream and cooked chicken.\n6. Simmer 10 minutes and serve with rice." },
        new Recipe { Id = 4, Title = "Vegetable Pad Thai", Category = "Thai", Ingredients = "Rice noodles\nTofu\nBean sprouts\nGreen onions\nPeanuts\nLime\nTamarind paste\nFish sauce\nSugar\nChili flakes", Steps = "1. Soak rice noodles in warm water 20 minutes.\n2. Press and cube tofu, then pan-fry until golden.\n3. Mix tamarind paste, fish sauce, sugar, and chili for sauce.\n4. Stir-fry noodles with sauce until coated.\n5. Add tofu and bean sprouts.\n6. Serve topped with peanuts, green onions, and lime." },
        new Recipe { Id = 5, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef\nTaco seasoning\nCorn tortillas\nLettuce\nTomato\nCheddar cheese\nSour cream\nSalsa", Steps = "1. Brown ground beef over medium-high heat.\n2. Add taco seasoning and water, simmer 5 minutes.\n3. Warm tortillas in a dry skillet.\n4. Fill tortillas with seasoned beef.\n5. Top with lettuce, tomato, cheese, sour cream, and salsa." },
        new Recipe { Id = 6, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados\nLime juice\nCilantro\nRed onion\nJalapeño\nTomato\nSalt", Steps = "1. Halve and pit avocados, scoop into a bowl.\n2. Mash to desired consistency.\n3. Stir in diced onion, jalapeño, tomato, and cilantro.\n4. Add lime juice and salt to taste.\n5. Serve immediately with tortilla chips." },
        new Recipe { Id = 7, Title = "Miso Soup", Category = "Japanese", Ingredients = "Dashi stock\nWhite miso paste\nTofu\nWakame seaweed\nGreen onions", Steps = "1. Bring dashi stock to a gentle simmer.\n2. Add cubed tofu and wakame.\n3. Remove from heat and whisk in miso paste.\n4. Serve topped with sliced green onions." },
        new Recipe { Id = 8, Title = "Chocolate Chip Cookies", Category = "Desserts", Ingredients = "Butter\nSugar\nBrown sugar\nEggs\nVanilla\nFlour\nBaking soda\nSalt\nChocolate chips", Steps = "1. Cream butter and sugars until fluffy.\n2. Beat in eggs and vanilla.\n3. Mix flour, baking soda, and salt; stir into wet ingredients.\n4. Fold in chocolate chips.\n5. Drop spoonfuls onto baking sheets.\n6. Bake at 375°F (190°C) for 9-11 minutes." },
    };
    private int _nextId = 9;

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars >= 1 && stars <= 5)
        {
            recipe.TotalRatingPoints += stars;
            recipe.RatingCount++;
        }
    }

    public Recipe AddRecipe(string title, string category, string ingredients, string steps)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = title,
            Category = category,
            Ingredients = ingredients,
            Steps = steps
        };
        _recipes.Add(recipe);
        return recipe;
    }
}
